import json
import pandas as pd
from datetime import datetime


FIELD_MAP = {
    "user_id": "user_id",
    "id": "user_id",
    "userId": "user_id",
    "email": "email",
    "email_address": "email",
    "full_name": "name",
    "name": "name",
    "userName": "name",
    "registration_date": "created_date",
    "created_at": "created_date",
    "joined": "created_date",
    "status": "status",
    "is_active": "status",
    "active": "status",
}

OUTPUT_COLUMNS = ["user_id", "name", "email", "created_date", "status"]


def normalize_date(value):
    if pd.isna(value) or value is None:
        return None
    s = str(value).strip()
    for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return s


def normalize_status(value):
    if pd.isna(value) or value is None:
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    s = str(value).strip().lower()
    if s in ("true", "1", "yes"):
        return "active"
    if s in ("false", "0", "no"):
        return "inactive"
    return s


def remap(df, source_label):
    renamed = {}
    for col in df.columns:
        if col in FIELD_MAP:
            renamed[col] = FIELD_MAP[col]
    df = df.rename(columns=renamed)
    # Keep only mapped columns
    known = [c for c in OUTPUT_COLUMNS if c in df.columns]
    df = df[known].copy()
    df["_source"] = source_label
    return df


def load_source_a():
    with open("/data/source_a/users.json") as f:
        records = json.load(f)
    df = pd.DataFrame(records)
    return remap(df, "source_a")


def load_source_b():
    df = pd.read_csv("/data/source_b/users.csv")
    return remap(df, "source_b")


def load_source_c():
    df = pd.read_parquet("/data/source_c/users.parquet")
    return remap(df, "source_c")


def merge_sources(frames):
    # frames ordered highest -> lowest priority
    all_users = {}  # user_id -> {field: {source: value}}

    for df in frames:
        for _, row in df.iterrows():
            uid = int(row["user_id"])
            src = row["_source"]
            if uid not in all_users:
                all_users[uid] = {}
            for field in OUTPUT_COLUMNS:
                if field == "user_id":
                    continue
                if field not in row or pd.isna(row[field]):
                    continue
                value = row[field]
                if field == "created_date":
                    value = normalize_date(value)
                elif field == "status":
                    value = normalize_status(value)
                else:
                    value = str(value).strip() if value is not None else None
                if value is None:
                    continue
                if field not in all_users[uid]:
                    all_users[uid][field] = {}
                all_users[uid][field][src] = value

    return all_users


def build_output_and_conflicts(all_users):
    source_priority = ["source_a", "source_b", "source_c"]
    output_rows = []
    conflicts = []

    for uid in sorted(all_users.keys()):
        fields = all_users[uid]
        row = {"user_id": uid}

        for field in OUTPUT_COLUMNS:
            if field == "user_id":
                continue
            if field not in fields:
                row[field] = None
                continue

            source_values = fields[field]
            # Select value from highest priority source that has it
            selected_value = None
            selected_source = None
            for src in source_priority:
                if src in source_values:
                    selected_value = source_values[src]
                    selected_source = src
                    break

            row[field] = selected_value

            # Conflict: more than one source has a value AND they differ
            distinct_values = set(source_values.values())
            if len(source_values) > 1 and len(distinct_values) > 1:
                conflict = {
                    "user_id": uid,
                    "field": field,
                    "values": {src: source_values[src] for src in source_priority if src in source_values},
                    "selected": selected_value,
                }
                conflicts.append(conflict)

        output_rows.append(row)

    return output_rows, conflicts


def main():
    frames = [load_source_a(), load_source_b(), load_source_c()]
    all_users = merge_sources(frames)
    output_rows, conflicts = build_output_and_conflicts(all_users)

    # Build output dataframe
    df_out = pd.DataFrame(output_rows, columns=OUTPUT_COLUMNS)
    df_out["user_id"] = df_out["user_id"].astype(int)
    df_out.to_parquet("/app/merged_users.parquet", index=False)
    print(f"Wrote {len(df_out)} rows to /app/merged_users.parquet")
    print(df_out.to_string())

    # Write conflict report
    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)
    print(f"\nWrote conflict report ({len(conflicts)} conflicts) to /app/conflicts.json")


if __name__ == "__main__":
    main()

